//! The inbox — where statement exports land, and the rule that stops one being counted twice.
//!
//! This is the FILE-DROP path, which the connection policy treats as the permanent floor: every
//! automated path against a site somebody else controls will break, so the manual one is never
//! removed. It is also the only path that works today, and it is not a stopgap — a person who has
//! just signed in to download an export is one click from dropping it here.
//!
//! # Counting a statement twice is the failure this exists to prevent
//!
//! Ingesting the same file again does not error. It doubles a month of spending, halves a runway and
//! moves a net worth, and every number stays perfectly plausible. So a file is CLAIMED once it has
//! been read — moved out of the inbox into `processed/` — and claiming is what makes the read
//! idempotent. A claim never overwrites: two exports that happen to share a name both survive, under
//! different ones, because losing the evidence is worse than an ugly filename.
//!
//! # An unrecognised name is refused, not guessed
//!
//! The institution decides which ingest profile reads the columns, and the wrong profile does not
//! fail — it reads a date as an amount, or a charge as a deposit, and reports it confidently. So a
//! file whose institution cannot be read off its name is listed as unreadable and left alone.

pub(crate) use free_path::free_path;
pub use inbox_dir::inbox_dir;
pub use processed_dir::processed_dir;
use std::path::{Path, PathBuf};

pub use institution_from_name::institution_from_name;
pub(crate) use is_statement::is_statement;
pub use render::render;

/// The institutions with an ingest profile. Longest first, so `bank-of-america` is tested before any
/// shorter id could shadow it.
pub const KNOWN: &[&str] = &["bank-of-america", "capital-one", "discover", "chase"];

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InboxFile {
    pub name: String,
    pub path: PathBuf,
    /// `None` means the name did not say which institution it came from.
    pub institution: Option<&'static str>,
    pub bytes: u64,
}

impl InboxFile {
    pub fn readable(&self) -> bool {
        self.institution.is_some()
    }
}

/// Everything waiting to be read. A directory that does not exist yet is EMPTY, not an error — an
/// inbox nobody has dropped anything into is the normal state, not a fault.
pub fn scan(dir: &Path) -> Result<Vec<InboxFile>, String> {
    if !dir.exists() {
        return Ok(Vec::new());
    }
    let entries = std::fs::read_dir(dir).map_err(|e| format!("cannot read {}: {e}", dir.display()))?;
    let mut out = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().to_string();
        if !is_statement(&name) {
            continue;
        }
        out.push(InboxFile {
            institution: institution_from_name(&name),
            bytes: entry.metadata().map(|m| m.len()).unwrap_or(0),
            name,
            path,
        });
    }
    // Stable order, so two runs report the same list and a diff of the report means something.
    out.sort_by(|a, b| a.name.cmp(&b.name));
    Ok(out)
}

/// Move a file out of the inbox, so reading it again is not possible by accident.
///
/// The timestamp goes in the NAME rather than being relied on from the filesystem: a copy across a
/// filesystem resets mtime, and the one question anybody asks of `processed/` is when a statement was
/// taken in.
pub fn claim(file: &Path, processed_dir: &Path, at: &str) -> Result<PathBuf, String> {
    std::fs::create_dir_all(processed_dir)
        .map_err(|e| format!("cannot create {}: {e}", processed_dir.display()))?;
    let name = file
        .file_name()
        .ok_or_else(|| format!("{} has no file name", file.display()))?
        .to_string_lossy()
        .to_string();
    let (stem, ext) = name.rsplit_once('.').unwrap_or((name.as_str(), ""));
    let stamp = at.replace([':', '-'], "");
    let dest = free_path(processed_dir, &format!("{stamp}-{stem}"), ext);

    if std::fs::rename(file, &dest).is_ok() {
        return Ok(dest);
    }
    // A rename fails across filesystems, which an inbox on a mounted volume genuinely is. Copy then
    // remove, and only remove once the copy is known to have landed.
    std::fs::copy(file, &dest).map_err(|e| format!("cannot copy {} to {}: {e}", file.display(), dest.display()))?;
    std::fs::remove_file(file).map_err(|e| format!("copied to {} but could not remove the original: {e}", dest.display()))?;
    Ok(dest)
}

#[cfg(test)]
mod tests {
    use super::*;

    // SYNTHETIC FIXTURES ONLY. No real statement belongs in this repo.
    struct Tmp(PathBuf);

    impl Tmp {
        fn new(tag: &str) -> Tmp {
            let p = std::env::temp_dir().join(format!("bsc-fin-inbox-{tag}-{}", std::process::id()));
            let _ = std::fs::remove_dir_all(&p);
            std::fs::create_dir_all(&p).unwrap();
            Tmp(p)
        }
        fn file(&self, name: &str, body: &str) -> PathBuf {
            let p = self.0.join(name);
            std::fs::write(&p, body).unwrap();
            p
        }
    }

    impl Drop for Tmp {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn a_name_that_starts_with_an_institution_is_read_as_that_institution() {
        assert_eq!(institution_from_name("chase-2026-07.csv"), Some("chase"));
        assert_eq!(institution_from_name("discover_july.csv"), Some("discover"));
        assert_eq!(institution_from_name("bank-of-america 2026.csv"), Some("bank-of-america"));
        assert_eq!(institution_from_name("capital-one.csv"), Some("capital-one"));
        assert_eq!(institution_from_name("CHASE-2026.CSV"), Some("chase"));
    }

    #[test]
    fn a_bare_prefix_is_not_a_match() {
        // `chaser-holdings.csv` is not a Chase export, and claiming it would read it with Chase's
        // column layout — which does not fail, it reports a date as an amount.
        assert_eq!(institution_from_name("chaser-holdings.csv"), None);
        assert_eq!(institution_from_name("discovery-fund.csv"), None);
    }

    #[test]
    fn an_unrecognised_name_is_refused_rather_than_guessed() {
        assert_eq!(institution_from_name("statement.csv"), None);
        assert_eq!(institution_from_name("2026-07-transactions.csv"), None);
        assert_eq!(institution_from_name(""), None);
    }

    #[test]
    fn scan_lists_csvs_and_ignores_everything_else() {
        let t = Tmp::new("scan");
        t.file("chase-2026-07.csv", "a,b\n");
        t.file("notes.txt", "x");
        t.file(".hidden.csv", "x");
        std::fs::create_dir_all(t.0.join("subdir.csv")).unwrap();
        let files = scan(&t.0).unwrap();
        assert_eq!(files.iter().map(|f| f.name.as_str()).collect::<Vec<_>>(), ["chase-2026-07.csv"]);
        assert!(files[0].readable());
        assert!(files[0].bytes > 0);
    }

    #[test]
    fn scan_reports_an_unreadable_file_rather_than_hiding_it() {
        let t = Tmp::new("unreadable");
        t.file("statement.csv", "a,b\n");
        let files = scan(&t.0).unwrap();
        assert_eq!(files.len(), 1);
        assert!(!files[0].readable());
        let text = render(&files);
        assert!(text.contains("UNREADABLE"), "{text}");
        assert!(text.contains("bank-of-america"), "{text}");
    }

    #[test]
    fn an_inbox_that_does_not_exist_yet_is_empty_not_an_error() {
        let missing = std::env::temp_dir().join("bsc-fin-inbox-never-created-xyz");
        let _ = std::fs::remove_dir_all(&missing);
        assert_eq!(scan(&missing).unwrap(), Vec::new());
        assert_eq!(render(&[]), "nothing waiting\n");
    }

    #[test]
    fn scan_is_stable_so_two_reports_can_be_compared() {
        let t = Tmp::new("stable");
        for n in ["discover-b.csv", "chase-a.csv", "capital-one-c.csv"] {
            t.file(n, "x");
        }
        let names: Vec<String> = scan(&t.0).unwrap().into_iter().map(|f| f.name).collect();
        assert_eq!(names, ["capital-one-c.csv", "chase-a.csv", "discover-b.csv"]);
        assert_eq!(scan(&t.0).unwrap().into_iter().map(|f| f.name).collect::<Vec<_>>(), names);
    }

    #[test]
    fn claiming_a_file_takes_it_out_of_the_inbox_so_it_cannot_be_read_twice() {
        // Reading the same statement again does not error. It doubles a month of spending and every
        // number stays perfectly plausible, which is why the move is the mechanism.
        let inbox = Tmp::new("claim-in");
        let done = Tmp::new("claim-out");
        let f = inbox.file("chase-2026-07.csv", "a,b\n");
        assert_eq!(scan(&inbox.0).unwrap().len(), 1);

        let dest = claim(&f, &done.0, "2026-07-01T12:00:00Z").unwrap();
        assert!(dest.exists());
        assert!(!f.exists());
        assert_eq!(scan(&inbox.0).unwrap().len(), 0);
    }

    #[test]
    fn a_claim_never_overwrites_an_earlier_one() {
        // Two exports that happen to share a name both survive. Losing the evidence of what was taken
        // in is worse than an ugly filename.
        let inbox = Tmp::new("dup-in");
        let done = Tmp::new("dup-out");
        let at = "2026-07-01T12:00:00Z";

        let first = claim(&inbox.file("chase.csv", "one"), &done.0, at).unwrap();
        let second = claim(&inbox.file("chase.csv", "two"), &done.0, at).unwrap();
        assert_ne!(first, second);
        assert_eq!(std::fs::read_to_string(&first).unwrap(), "one");
        assert_eq!(std::fs::read_to_string(&second).unwrap(), "two");
    }

    #[test]
    fn the_claim_name_carries_when_rather_than_trusting_the_filesystem() {
        // A copy across a filesystem resets mtime, and when a statement was taken in is the one
        // question anybody asks of `processed/`.
        let inbox = Tmp::new("stamp-in");
        let done = Tmp::new("stamp-out");
        let dest = claim(&inbox.file("chase-2026-07.csv", "x"), &done.0, "2026-07-01T12:00:00Z").unwrap();
        let name = dest.file_name().unwrap().to_string_lossy().to_string();
        assert!(name.starts_with("20260701T120000Z-"), "{name}");
        assert!(name.ends_with(".csv"), "{name}");
        assert!(name.contains("chase-2026-07"), "{name}");
    }

    #[test]
    fn claiming_creates_the_processed_directory_rather_than_failing() {
        let inbox = Tmp::new("mkdir-in");
        let parent = Tmp::new("mkdir-out");
        let nested = parent.0.join("a").join("b");
        let dest = claim(&inbox.file("chase.csv", "x"), &nested, "2026-07-01T12:00:00Z").unwrap();
        assert!(dest.exists());
    }

    #[test]
    fn claiming_something_that_is_not_there_is_an_error_naming_it() {
        let done = Tmp::new("gone-out");
        let missing = std::env::temp_dir().join("bsc-fin-not-a-file-xyz.csv");
        let _ = std::fs::remove_file(&missing);
        let e = claim(&missing, &done.0, "2026-07-01T12:00:00Z").unwrap_err();
        assert!(e.contains("bsc-fin-not-a-file-xyz.csv"), "{e}");
    }

    #[test]
    fn every_known_institution_is_one_the_statement_profiles_can_read() {
        // A name this accepts and the parser then rejects would be a promise the next step breaks.
        for id in KNOWN {
            assert!(institution_from_name(&format!("{id}-2026-07.csv")).is_some(), "{id}");
        }
        assert_eq!(KNOWN.len(), 4);
    }
}
